import unittest
from billing import total

class TotalTests(unittest.TestCase):
    def test_total(self):
        self.assertEqual(total([2, 3]), 5)

    def test_total_includes_credits(self):
        self.assertEqual(total([10, -3, -2]), 5)

    def test_empty_invoice_totals_zero(self):
        self.assertEqual(total([]), 0)

    def test_total_preserves_input(self):
        amounts = [10, -3, -2]
        total(amounts)
        self.assertEqual(amounts, [10, -3, -2])

